def main():
    path=ROOT/'translation/batches/415_rise_statuses.generated.json';assert not path.exists()
    catalog={r['key']:r for r in read(ROOT/'translation/catalog.working.json')};sources=defaultdict(list)
    for m,values in TEXT.items():
        assert len(values)==20
        s=f'export_base/battle/support/bsv105.bvp_({m:03}).BMD.json';doc=read(ROOT/s)
        for i,body in zip(IDS,values):
            r=catalog[f'{s}:{i}:0'];assert not r.get('translation');body+='\n'
            a=TOKEN.sub('',r['original']).splitlines();b=body.splitlines()
            assert len(b)<=len(a) and max(map(len,b))<=max(map(len,a)),(m,i,a,b)
            sources[s].append([i,0,doc['texts'][i]['id'],body])
    write(path,dict(status='draft',sources=dict(sources),source_hashes={s:hashlib.sha256((ROOT/s).read_bytes()).hexdigest() for s in sources},review_notes=['理世054—060七组140页，保留14页占位。称呼沿用既有前辈/花村前辈/小虎/乾等。','麻痹不写成必定不能行动；诅咒明确主动攻击伤及自身。未运行验证。']))
    print('Rise status pages:',sum(map(len,sources.values())))

if __name__=='__main__':main()
